(function(scope){const KEY='worldMap:main',actions=['work','train','study','explore','rest'];function image(value){if(typeof value!=='string'||value.length>1100000||value&&!/^(https?:\/\/|data:image\/(png|jpeg|webp|gif);base64,)/i.test(value))throw Error('รูปแผนที่หรือไอคอนไม่ถูกต้อง');return value;}function id(value){if(typeof value!=='string'||!/^[a-zA-Z0-9_-]{1,80}$/.test(value))throw Error('รหัสแผนที่หรือสถานที่ไม่ถูกต้อง');return value;}function text(value,max,label){if(typeof value!=='string'||value.length>max)throw Error(label+' ยาวเกินกำหนด');return value;}function validate(input){if(!input||input.version!==1||!Array.isArray(input.maps)||input.maps.length<1||input.maps.length>20)throw Error('รองรับแผนที่ 1–20 แผ่น');const out={version:1,rootId:id(input.rootId),maps:input.maps.map(m=>{if(!m||!m.name?.trim()||!Array.isArray(m.locations)||m.locations.length>80)throw Error('ตรวจชื่อแผนที่และจำนวนสถานที่ (ไม่เกิน 80 จุดต่อแผ่น)');if(!Number.isFinite(m.width)||m.width<1||m.width>10000||!Number.isFinite(m.height)||m.height<1||m.height>10000)throw Error('ขนาดแผนที่ไม่ถูกต้อง');return {id:id(m.id),name:text(m.name.trim(),80,'ชื่อแผนที่'),image:image(m.image||''),width:m.width,height:m.height,locations:m.locations.map(p=>{if(!p||!p.name?.trim()||!Number.isFinite(p.x)||p.x<0||p.x>100||!Number.isFinite(p.y)||p.y<0||p.y>100||!Array.isArray(p.activities)||p.activities.some(a=>!actions.includes(a)))throw Error('ข้อมูลสถานที่หรือพิกัดไม่ถูกต้อง');return {id:id(p.id),name:text(p.name.trim(),80,'ชื่อสถานที่'),icon:text(p.icon||'📍',16,'ไอคอน'),iconImage:image(p.iconImage||''),x:p.x,y:p.y,description:text(p.description||'',2000,'คำอธิบาย'),targetMapId:p.targetMapId?id(p.targetMapId):null,activities:[...new Set(p.activities)],enabled:p.enabled!==false};})};})};const ids=new Set(out.maps.map(m=>m.id));if(ids.size!==out.maps.length||!ids.has(out.rootId))throw Error('รหัสแผนที่ซ้ำหรือไม่มีแผนที่หลัก');for(const m of out.maps){if(new Set(m.locations.map(p=>p.id)).size!==m.locations.length)throw Error('รหัสสถานที่ซ้ำ');for(const p of m.locations)if(p.targetMapId&&(!ids.has(p.targetMapId)||p.targetMapId===m.id))throw Error('ปลายทางต้องเป็นแผนที่อื่นที่มีอยู่');}return out;}
function defaults(){return {version:1,rootId:'world',maps:[{id:'world',name:'Decide Fate',image:'',width:800,height:440,locations:[['work','ย่านช่างฝีมือ','⚒',20,29,'ทำงานในโรงช่างและหาเงิน'],['train','ลานฝึก','⚔',50,43,'ฝึกดาบและความชำนาญอาวุธ'],['explore','ป่ากระซิบ','🌲',79,23,'ออกสำรวจป่าและค้นพบสิ่งใหม่'],['rest','โรงเตี๊ยม','☾',22,77,'พักฟื้นสุขภาพ พลังงาน และมานา'],['study','หอเวท','✧',70,78,'เรียนเวทและค้นคว้าความรู้']].map(([a,name,icon,x,y,description])=>({id:a,name,icon,iconImage:'',x,y,description,targetMapId:null,activities:[a],enabled:true}))}]};}
function position(clientX,clientY,rect){return {x:Math.max(0,Math.min(100,(clientX-rect.left)/rect.width*100)),y:Math.max(0,Math.min(100,(clientY-rect.top)/rect.height*100))};}
const api={KEY,actions,image,validate,defaults,position};scope.EvervaleMapData=api;if(typeof module!=='undefined')module.exports=api;})(typeof window==='undefined'?globalThis:window);
